public static System.Object createCLRList(System.Object baseObject)
{
    System.Type baseType = baseObject.GetType();
    System.Object crtList = Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.TypeHelperForAx::CreateListOfType(baseType);

    return crtList;
}

public static System.Object createCLRStringSet()
{
    System.Object stringSet = Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.TypeHelperForAx::CreateSetOfString();

    return stringSet;
}

public static Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingMatchingDimension initMatchingDimensionFromInventDim(InventDimId inventDimId)
{
    InventDim inventdim;

    if (inventDimId == '')
    {
        inventDim = InventDim::findOrCreateBlank();
    }
    else
    {
        select firstonly inventdim where inventdim.inventDimId == inventDimId;
    }

    return GUPRetailPricingDataManager::ConvertToCrtInventoryDimension(inventdim);
}

public static CLRObject initMatchingRules(RecId pricingRuleHeaderRecId, RecId pricingRuleLineRecId)
{
    CLRObject rules = GUPMatchingEntityHelper::createCLRList(new Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingMatchingRule());

    rules.Add(GUPRetailPricingDataManager::ConvertToCrtPricingRule(pricingRuleHeaderRecId));
    rules.Add(GUPRetailPricingDataManager::ConvertToCrtPricingRule(pricingRuleLineRecId));

    return rules;
}

public static Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.IPricingDataAccessor initializeDataAcessor(SalesId salesId)
{
    Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.IPricingDataAccessor pricingManager;

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        RetailTempOrderItem tempOrderItem;
        pricingManager = new GUPRetailPricingDataManager(0, salesId);
    }

    return pricingManager;
}
